// Filtra registros aprobados tolerando cualquier formato (TRUE, VERDADERO, checkbox, texto tabulado)
const items = $input.all();
const pendingItems = [];

function isTruthy(val) {
  if (val === true || val === 1) return true;
  if (!val) return false;
  const s = String(val).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === '1' || s === 'SI' || s === 'SÍ' || s === 'V' || s === 'OK' || s === 'CHECKED';
}

function isProcessed(val) {
  if (val === true || val === 1) return true;
  if (!val) return false;
  const s = String(val).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === '1';
}

for (let i = 0; i < items.length; i++) {
  let row = items[i].json || {};

  const keys = Object.keys(row);
  if (keys.length === 1 && (keys[0].includes('\t') || String(row[keys[0]]).includes('\t'))) {
    const rawHeaders = keys[0].split('\t').map(h => h.trim());
    const rawValues = String(row[keys[0]]).split('\t').map(v => v.trim());
    const reconstructed = {};
    for (let j = 0; j < rawHeaders.length; j++) {
      reconstructed[rawHeaders[j]] = rawValues[j] || '';
    }
    row = reconstructed;
  }

  let messageId = '';
  let approvedVal = null;
  let processedVal = null;
  let attachmentName = '';

  for (const [k, v] of Object.entries(row)) {
    const cleanKey = k.trim().toLowerCase();
    if (cleanKey === 'id_mensaje' || cleanKey.includes('mensaje')) messageId = String(v).trim();
    if (cleanKey === 'aprobado' || cleanKey.includes('aprobado')) approvedVal = v;
    if (cleanKey === 'procesado' || cleanKey.includes('procesado')) processedVal = v;
    if (cleanKey === 'nombre_adjunto' || cleanKey.includes('adjunto')) attachmentName = String(v).trim();
  }

  if (!messageId && keys.length > 0) {
    const firstVal = String(row[keys[0]]).trim();
    if (/^[a-f0-9]{16}$/i.test(firstVal)) {
      messageId = firstVal;
    }
  }

  if (messageId && isTruthy(approvedVal) && !isProcessed(processedVal)) {
    pendingItems.push({
      json: {
        ...row,
        ID_Mensaje: messageId,
        Nombre_Adjunto: attachmentName || row.Nombre_Adjunto || 'Nomina.zip',
        _rowIndex: i + 2
      }
    });
  }
}

return pendingItems;

const zlib = require('zlib');

// --- MOTOR CRIPTOGRÁFICO PKWARE ZIPCRYPTO ---
function makeCrcTable() {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (-306674912 ^ (c >>> 1)) : (c >>> 1); 
    }
    table[n] = c;
  }
  return table;
}
const crcTable = makeCrcTable();
function crc32Update(crc, b) {
  return (crc >>> 8) ^ crcTable[(crc ^ b) & 0xff];
}

class ZipCrypto {
  constructor(password) {
    this.key0 = 305419896;
    this.key1 = 591751049;
    this.key2 = 878082192;
    for (let i = 0; i < password.length; i++) {
      this.updateKeys(password.charCodeAt(i));
    }
  }
  updateKeys(c) {
    this.key0 = crc32Update(this.key0, c);
    this.key1 = Math.imul(this.key1 + (this.key0 & 0xff), 134775813) + 1 | 0;
    this.key2 = crc32Update(this.key2, (this.key1 >>> 24) & 0xff);
  }
  decryptByte(c) {
    const temp = (this.key2 & 0xffff) | 2;
    const k = Math.imul(temp, temp ^ 1) >>> 8 & 0xff;
    const p = c ^ k;
    this.updateKeys(p);
    return p;
  }
  decryptBuffer(buf) {
    const out = Buffer.alloc(buf.length);
    for (let i = 0; i < buf.length; i++) {
      out[i] = this.decryptByte(buf[i]);
    }
    return out;
  }
}

function extractZipBufferFromMime(rawString) {
  let mimeText = rawString;
  if (!rawString.includes('Content-Type') && !rawString.includes('Received:')) {
    mimeText = Buffer.from(rawString.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
  }

  // 1. Buscar partes MIME delimitadas por boundaries
  const parts = mimeText.split(/--[^\r\n]+/);
  for (const part of parts) {
    if (/content-transfer-encoding:\s*base64/i.test(part) || /filename=[^\r\n]+\.zip/i.test(part) || /application\/(?:x-)?zip/i.test(part)) {
      const lines = part.split(/\r?\n/);
      let isBody = false;
      let b64Lines = [];
      for (const line of lines) {
        if (isBody) {
          const trimmed = line.trim();
          if (trimmed.length > 0 && /^[A-Za-z0-9+/=]+$/.test(trimmed)) {
            b64Lines.push(trimmed);
          }
        } else if (line.trim() === '') {
          isBody = true;
        }
      }
      if (b64Lines.length > 0) {
        const buf = Buffer.from(b64Lines.join(''), 'base64');
        if (buf.length > 30 && buf.readUInt32LE(0) === 0x04034b50) {
          return buf;
        }
      }
    }
  }

  // 2. Búsqueda directa de bloques Base64 que inicien con firma ZIP (UEsDB)
  const matches = mimeText.match(/(?:UEsDB[A-Za-z0-9+/=\r\n]{100,})/g);
  if (matches) {
    for (const m of matches) {
      const buf = Buffer.from(m.replace(/[\r\n\s]/g, ''), 'base64');
      if (buf.length > 30 && buf.readUInt32LE(0) === 0x04034b50) {
        return buf;
      }
    }
  }

  return null;
}

const items = $input.all();
const filterItems = $('Filter (Aprobado == TRUE & Procesado == FALSE)').all();
const outputItems = [];
const password = process.env.ZIP_PASSWORD || '<YOUR_ZIP_PASSWORD>';

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const rowMeta = filterItems[idx] ? filterItems[idx].json : (item.json || {});
  const rawData = (item.json && item.json.raw) ? item.json.raw : '';

  if (!rawData) {
    throw new Error(`No se pudo obtener el cuerpo crudo del correo ${rowMeta.ID_Mensaje}`);
  }

  const zipBuffer = extractZipBufferFromMime(rawData);
  if (!zipBuffer) {
    throw new Error(`No se encontró el fichero ZIP dentro del correo crudo ${rowMeta.ID_Mensaje}`);
  }

  let offset = 0;
  let extractedPdfBuffer = null;
  let extractedFilename = 'Nomina.pdf';

  while (offset < zipBuffer.length - 30) {
    const signature = zipBuffer.readUInt32LE(offset);
    if (signature !== 0x04034b50) {
      offset++;
      continue;
    }
    const flags = zipBuffer.readUInt16LE(offset + 6);
    const compMethod = zipBuffer.readUInt16LE(offset + 8);
    const compSize = zipBuffer.readUInt32LE(offset + 18);
    const fnLen = zipBuffer.readUInt16LE(offset + 26);
    const extraLen = zipBuffer.readUInt16LE(offset + 28);
    const filename = zipBuffer.toString('utf8', offset + 30, offset + 30 + fnLen);
    const dataOffset = offset + 30 + fnLen + extraLen;
    const isEncrypted = (flags & 0x0001) !== 0;

    let payload = zipBuffer.subarray(dataOffset, dataOffset + compSize);
    if (isEncrypted) {
      const cipher = new ZipCrypto(password);
      const decrypted = cipher.decryptBuffer(payload);
      payload = decrypted.subarray(12);
    }

    let uncompressed;
    try {
      if (compMethod === 8) {
        uncompressed = zlib.inflateRawSync(payload);
      } else if (compMethod === 0) {
        uncompressed = payload;
      } else {
        throw new Error(`Método de compresión no soportado: ${compMethod}`);
      }
    } catch (err) {
      throw new Error(`Error al descomprimir ${filename} (posible contraseña incorrecta o archivo corrupto): ${err.message}`);
    }

    extractedPdfBuffer = uncompressed;
    extractedFilename = filename.endsWith('.pdf') ? filename : `${filename}.pdf`;
    break;
  }

  if (!extractedPdfBuffer) {
    throw new Error(`No se pudo extraer el PDF dentro del ZIP de ${rowMeta.ID_Mensaje}.`);
  }

  const base64Pdf = extractedPdfBuffer.toString('base64');

  outputItems.push({
    json: {
      ...rowMeta,
      extracted_filename: extractedFilename,
      pdf_base64: base64Pdf
    },
    binary: {
      data: {
        data: base64Pdf,
        mimeType: 'application/pdf',
        fileName: extractedFilename
      }
    }
  });
}

return outputItems;

