const geminiRaw = $input.first().json;
const driveFile = $('Upload PDF to Drive').first().json;
const rowData = $('Decompress Password ZIP (In-Memory)').first().json;

let rawText = '';
if (geminiRaw.candidates && geminiRaw.candidates[0] && geminiRaw.candidates[0].content && geminiRaw.candidates[0].content.parts) {
  for (const p of geminiRaw.candidates[0].content.parts) {
    if (p.text && p.text.trim().startsWith('{')) {
      rawText = p.text;
      break;
    }
    if (p.text && !p.thought) {
      rawText = p.text;
    }
  }
  if (!rawText && geminiRaw.candidates[0].content.parts[0]) {
    rawText = geminiRaw.candidates[0].content.parts[0].text || '';
  }
}

let parsedGemini = {};
try {
  const cleanJson = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  parsedGemini = JSON.parse(cleanJson);
} catch (e) {
  throw new Error(`Error parseando JSON de Gemini Pro: ${e.message}. Texto recibido: ${rawText}`);
}

const formattedMonth = String(parsedGemini.mes || '').padStart(2, '0');
const year = String(parsedGemini.anio || new Date().getFullYear());
const viewLink = driveFile.webViewLink || `https://drive.google.com/file/d/${driveFile.id}/view`;

return [{
  json: {
    ID_Mensaje: rowData.ID_Mensaje,
    Procesado: true,
    _target_sheet: year,
    'Mes': parsedGemini.mes,
    'Tipo': parsedGemini.tipo_nomina,
    'Total Bruto (€)': Number(parsedGemini.total_devengado_bruto || 0),
    'Aportación SS (€)': Number(parsedGemini.aportaciones_ss_trabajador || 0),
    '% IRPF': Number(parsedGemini.porcentaje_irpf || 0),
    'Retención IRPF (€)': Number(parsedGemini.importe_irpf || 0),
    'Líquido Neto (€)': Number(parsedGemini.liquido_percibir_neto || 0),
    'Enlace Drive PDF': viewLink
  }
}];
